b = Bank("ing", "ing", "Inglés")
# ---------------- 1.º ----------------
b.mc("Colours", 1, 1, "What colour is a banana?", "Yellow", ["Blue", "Red", "Green"], "Think of a banana.", "A banana is yellow (amarillo).")
