b.mc("Superlatives", 2, 5, "Mount Teide is the ___ mountain in Spain.", "highest", ["higher", "high", "most high"], "The + -est.", "high → the highest.")
b.mc("Quantity", 1, 5, "How ___ apples are there?", "many", ["much", "lot", "some"], "Apples are countable.", "How many + countable.")
